// Server-only: read the engine's published tool catalogue (public/reference/tools.json) and turn it into rate rows.
//
// That file is generated by the engine itself and diffed in CI, so units per endpoint here are the units the
// engine meters. If it cannot be read the answer is an empty list, and every consumer renders "not available"
// instead of a guess.

import fs from "node:fs/promises";
import fsSync from "node:fs";
import path from "node:path";
import { parseToolRates, type ToolRate } from "@/lib/payg-pricing";

export async function readToolRates(): Promise<ToolRate[]> {
  try {
    const raw = await fs.readFile(path.join(process.cwd(), "public", "reference", "tools.json"), "utf8");
    return parseToolRates(JSON.parse(raw));
  } catch {
    return [];
  }
}

/** Synchronous variant for statically rendered pages (pricing). Same file, same fallback. */
export function readToolRatesSync(): ToolRate[] {
  try {
    const raw = fsSync.readFileSync(path.join(process.cwd(), "public", "reference", "tools.json"), "utf8");
    return parseToolRates(JSON.parse(raw));
  } catch {
    return [];
  }
}
